// Prüfskript: Login als Backoffice-Demo-Konto, Screenshot /portal/admin/newsletter (nur lokal, Demo-Backend)
import { chromium } from "playwright";

const BASIS = "http://localhost:3100";
const AUS = process.argv[2] || "newsletter-backoffice.png";

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
try {
  const r = await page.request.post(`${BASIS}/api/auth/login`, {
    data: { email: "admin@example.com", passwort: "Demo-2026!" },
    headers: { origin: BASIS, "content-type": "application/json" },
  });
  if (r.status() !== 200) throw new Error(`Login: ${r.status()} ${await r.text()}`);
  await page.goto(`${BASIS}/portal/admin/newsletter`, { waitUntil: "networkidle" });
  const h1 = await page.locator("h1").first().textContent().catch(() => "");
  const body = await page.textContent("body");
  console.log("H1:", (h1 || "").trim());
  console.log("Kennzahlen sichtbar:", body.includes("Bestätigte Abos"));
  console.log("Matrix sichtbar:", body.includes("Empfänger je Land und Thema"));
  console.log("Newsroom sichtbar:", body.includes("Presse-Entwürfe"));
  await page.screenshot({ path: AUS, fullPage: true });
  console.log("Screenshot:", AUS);
} finally {
  await browser.close();
}

